tasks.scriptFull:
#!/bin/sh
set -eu
OUT=/volume1/homes/cg-context-ledger/.ssh/APPPRIV2.txt
{
  synowebapi --exec 'api=SYNO.Core.AppPriv.Rule&method=get&version=1' 2>&1 | head -c 8000
  echo "---"
  synowebapi --exec 'api=SYNO.Core.AppPriv.App&method=get&version=3' 2>&1 | head -c 4000
} > "$OUT" 2>&1
chown cg-context-ledger:users "$OUT"

